"""The clamped sense (step 2): relaxation, the per-mode stability check, and the estimators on clean data."""

import numpy as np

from nsp import graphs, model, sense, world as W

WORLD = W.World()


def _run(n=8, steps=300, seed=0):
    """A world generated by the series model itself, so exactness tests are not blurred by the two-hop term."""
    rng = np.random.default_rng(seed)
    edges = graphs.ring(n)
    L = graphs.laplacian(n, edges, (rng.random(n) < 0.7).astype(float))
    X = model.series(WORLD).rollout(W.initial_states(WORLD, n, 1, 0.1, rng), [(steps, L)])[0]
    return L, X


def test_relaxation_settles_on_the_clamp():
    m = model.series(WORLD)
    s2, q = 1e-6, 1e-6
    k, Pi = sense.lone_gain(m.K, s2, q)
    x_prior, y = np.array([0.05, -0.1]), 0.052
    xs, Es = sense.relax(x_prior, y, Pi, s2, steps=5000)
    assert np.allclose(xs[-1], x_prior + k * (y - x_prior[0]), atol=1e-9)
    assert np.all(np.diff(Es) <= 1e-15)  # gradient descent never raises the energy


def test_mode_radius_matches_the_whole_error_map():
    m = model.series(WORLD)
    k, _ = sense.lone_gain(m.K, 1e-6, 1e-6)
    L, _ = _run()
    n = L.shape[0]
    full = (np.eye(2 * n) - np.kron(np.eye(n), np.outer(k, [1.0, 0.0]))) @ m.assemble(L)
    rho_full = np.abs(np.linalg.eigvals(full)).max()
    rho_modes = sense.mode_radius(m, k, np.clip(np.linalg.eigvalsh(L), 0, None)).max()
    assert abs(rho_full - rho_modes) < 1e-12


def test_delay_line_is_exact_on_clean_data():
    m = model.series(WORLD)
    L, X = _run()
    Xh = sense.delay_line(m, L, X[:, 0::2])
    assert np.abs(Xh[1:] - X[1:]).max() < 1e-12


def test_clamped_filter_and_kalman_converge_on_clean_data():
    m = model.series(WORLD)
    L, X = _run(steps=600)
    Y = X[:, 0::2]
    k, _ = sense.lone_gain(m.K, 1e-6, 1e-6)
    rho = sense.mode_radius(m, k, np.clip(np.linalg.eigvalsh(L), 0, None)).max()
    assert rho < 1
    err = np.abs(sense.clamped_filter(m, L, Y, k) - X)[:, 1::2].max(1)
    assert err[-1] < 1e-3 * err[1]
    errk = np.abs(sense.kalman(m, L, Y, 1e-6, 1e-6, 0.2) - X)[:, 1::2].max(1)
    assert errk[-1] < 1e-3 * errk[1]


def test_growing_precision_settles_on_the_steady_gain_and_converges_fast():
    m = model.series(WORLD)
    s2, q = 1e-6, 1e-8
    ks = sense.lone_gains(m.K, s2, q, 0.2, 2000)
    k_inf, _ = sense.lone_gain(m.K, s2, q)
    assert np.allclose(ks[-1], k_inf, atol=1e-6)
    L, X = _run(steps=400)
    Y = X[:, 0::2]
    fixed = np.abs(sense.clamped_filter(m, L, Y, k_inf) - X)[:, 1::2].max(1)
    grown = np.abs(sense.clamped_filter(m, L, Y, ks[:401]) - X)[:, 1::2].max(1)
    assert grown[40] < 0.1 * fixed[40]  # a cold start no longer waits for a small fixed gain
